    languages: ['Korean'],
    context: 'The Democratic People\'s Republic of Korea is unlike anywhere else on earth. The portraits of Kim Il-sung and Kim Jong-il hang in every home, every classroom, every workplace — not as a choice but as a requirement. The Kim family is not merely the government; the ideology of Juche (self-reliance) and the quasi-divine status of the Suryong (Great Leader) are the water the country swims in. Every citizen has a Songbun — a class status determined by their family\'s political loyalty going back three generations. Those in the hostile class (relatives who fled South, collaborated with Japan, had religion) face permanent barriers to education, work, and Pyongyang residency. The Public Distribution System provided rations until the 1990s; when it collapsed in 1994, between 300,000 and 1 million people died in the famine called the Arduous March. The informal jangmadang (market) grew from survival necessity and remains technically illegal while being tolerated as economically necessary. USB drives smuggled across the Chinese border carry South Korean dramas, films, and music — information the state has tried to prohibit. The Tumen River at its shallowest is knee-deep and crossable at night. China sends back those caught. Getting to a third country — Mongolia or Thailand — is the route to South Korea. The Hanawon resettlement center awaits. The gap between what North Koreans are told about the world and what the world is has been both the system\'s greatest weapon and its greatest vulnerability.',
