    languages: ['Azerbaijani', 'Russian'],
    context: 'Azerbaijan sits between Russia, Iran, Georgia, and Armenia. Baku was the world\'s first oil city — the Nobel brothers made their fortune here in the 1870s — and oil explains everything about the 20th and 21st century: the Soviet annexation, the Aliyev family\'s three-decade grip. Shia Islam shapes personal morality and death rituals without producing political Islamism; Azerbaijanis drink, celebrate Nowruz, and consider themselves secular without contradiction. The Nagorno-Karabakh conflict defined national identity from 1988 onward: a third of the country were IDPs, living in unfinished Soviet buildings and shipping containers for thirty years, waiting. The 1990 Black January massacre — Soviet troops killing pro-independence demonstrators in Baku — sits alongside the Karabakh loss in national memory. When the 2020 war ended with Azerbaijani victory and the 2023 offensive retook all of Karabakh, people wept in the streets. The flag, the army, the map — finally complete. What to do with thirty years of grief when you\'ve won.',
