    languages: ['Kazakh', 'Russian'],
    context: 'Kazakhstan is vast — the ninth largest country on earth — and the steppe is genuinely immense: you can drive for hours and see nothing but grass and sky. Oil from the Tengiz and Kashagan fields made the state wealthy after 1991, but that wealth pooled at the top. Nazarbayev ruled for three decades and renamed the capital after himself; his name was later quietly removed. Ethnic Kazakhs and ethnic Russians navigate a coexistence shaped by the Soviet deportation policy that made Kazakhstan a dumping ground for Chechens, Koreans, Germans, and Volga Tatars as well — the country is stranger and more diverse than it looks on a map. Bribery at traffic stops is understood as a transaction with an informal price. Hospitality requires that the guest eat before the host; refusing food is an insult that persists. Russian is still the language of business in Almaty even as Kazakh is promoted. The 1929–33 collectivisation famine killed perhaps 1.5 million Kazakhs — 38 percent of the Kazakh population — a wound still not fully named in the national story.',
