    languages: ['Uzbek', 'Russian'],
    context: 'Uzbekistan occupies the ancient heart of the Silk Road — Samarkand, Bukhara, and Khiva are among the oldest continuously inhabited cities in Central Asia — but its modern state was shaped entirely by Soviet monoculture. Stalin turned the country into a cotton machine: one crop, wall to wall, draining the rivers that fed the Aral Sea until fishing boats sat stranded on salt flats forty kilometres from where the water used to be. Karimov ruled from 1989 until his death in 2016, one of the most totalitarian governments outside North Korea: the mahalla (neighbourhood committee) watched and reported, schools were closed in September so children could pick cotton, and in 2005 the army shot several hundred protesters in Andijan and the government denied it happened. Weddings require a feast that families go into debt to provide. Plov — rice cooked in cottonseed oil with carrots and lamb — is not just food; correctly preparing it is a matter of masculine identity. Tashkent was largely rebuilt in Soviet brutalist style after the 1966 earthquake.',
