    languages: ['Kyrgyz', 'Russian'],
    context: 'Kyrgyzstan is the most democratic of the Central Asian republics — by regional standards, which is a low bar. Three presidents have been overthrown since independence: the Tulip Revolution of 2005 sent Akayev into exile, and the 2010 uprising forced Bakiyev to flee. In the same year, ethnic violence between Kyrgyz and Uzbeks in the southern city of Osh killed hundreds and displaced hundreds of thousands. The country has almost no oil or gas and depends on gold mining, remittances from workers in Russia and Kazakhstan, and a small re-export trade through the Chinese border. The mountains are genuine — over 90 percent of the country is above 1,500 metres — and the landscape defined the traditional nomadic culture that was collectivised and destroyed under Stalin. The word *manas* carries the weight of the longest oral epic in world literature, recited by specialist singers from memory for centuries before it was ever written down. Independence from Moscow meant sudden poverty: Soviet subsidies stopped, factories closed, and the professional class that had staffed Soviet institutions found their credentials worthless overnight.',
