    languages: ['Tajik', 'Russian', 'Uzbek'],
    context: 'Tajikistan fought a civil war from 1992 to 1997 that killed between 50,000 and 100,000 people and displaced a tenth of the population — a war between the Soviet-era government backed by Russia and Uzbekistan, Islamic opposition groups, and regional warlords from Gharm and the Pamirs whose motivations did not map cleanly onto any of those categories. Rahmon has ruled since 1994 and is now called "Leader of the Nation" by law. A quarter of the country\'s GDP comes from men working in Russia and sending money home — when Russia\'s economy contracts, Tajikistan\'s does too. The Gorno-Badakhshan Autonomous Oblast in the Pamirs is physically isolated, ethnically distinct, speaks Iranian languages unlike the rest of the country, and is periodically besieged by the central government. Dushanbe was a small village called Dyushambe until the Soviets industrialised it; the old bazaar culture is almost entirely gone. Cotton, aluminium, and hydropower are the economy; the rivers that power the dams flow downstream to Uzbekistan, whose agriculture depends on them, which means water is a permanent source of regional tension.',
