    languages: ['Turkmen', 'Russian'],
    context: 'Turkmenistan is one of the most isolated countries on earth, not by geography but by design. Saparmurat Niyazov renamed himself Turkmenbashi — Father of all Turkmen — renamed the months of the year after members of his family, banned opera and ballet and the circus, required civil servants to memorise his spiritual autobiography (the Ruhnama) as a condition of employment, and built a rotating golden statue of himself in the capital. He also sat on the world\'s fourth largest natural gas reserves and distributed almost none of the wealth. He died in 2006; his successor Berdymukhamedov called himself Arkadag (Patron) and had his portrait on cereal boxes. The capital Ashgabat has been rebuilt in white marble as an elaborate monument to the regime — vast empty boulevards, gold-domed palaces, fountains in the desert — while ordinary Turkmen queue for bread with ration cards. Information leaving the country is controlled; what reaches the outside world is fragmentary. The Karakum Desert covers 70 percent of the country\'s surface, and the Darvaza gas crater has been burning since a Soviet drill rig collapsed in 1971.',
