    context: 'Vietnam carries the weight of its American war while building something new at remarkable speed. The Communist Party controls political life but has broadly freed the economy. Motorbikes crowd every city. Family obligation runs deep, and individual ambition is increasingly rewarded. Crossing the street in Hanoi means walking steadily into the flow — stopping is dangerous. Gọi xe (bike-hailing apps) replaced the xe ôm (motorbike taxi) in five years. Mặt tiền (street frontage) determines a family\'s status — a narrow house with a wide front is everything. Ancestor worship is not religion in the Western sense; it is maintenance of the family system.',
