    languages: ['Tigrinya', 'Arabic', 'English', 'Tigre'],
    context: 'Eritrea won its independence from Ethiopia in 1993 after thirty years of armed struggle — one of the longest liberation wars in African history. Independence day was a moment of genuine, collective joy. Within a decade, the ruling PFDJ party under President Isaias Afwerki had dismantled every institution that could challenge it: the independent press was shut in 2001, the G-15 reformers arrested and held without trial. The Warsay-Yikaalo development campaign imposed indefinite national service; Eritreans can be called up in their teens and held for twenty years with no end date and no formal salary. This, more than anything, is why the country empties — by 2015 Eritrea was the fourth-largest source of Mediterranean crossings, from a nation of 3.5 million. Asmara is one of the finest examples of Art Deco Italian colonial architecture in the world. The country is Orthodox Christian in the highlands, Muslim in the lowlands, and that coexistence has mostly held even as everything else has broken down.',
