    context: 'Israel was established in 1948 after the Holocaust, the British Mandate period, and a war fought simultaneously with Arab neighbours and a collapsing British administration. The founding generation built a state from almost nothing while absorbing mass immigration: Mizrahi Jews from Arab countries arrived in the 1950s and 1960s, often to transit camps (ma\'abarot) and development towns at the desert\'s edge — a pattern of discrimination that created a socioeconomic divide still felt today. Soviet Jews arrived by the million between 1990 and 1995. Ethiopian Jews arrived in dramatic airlifts in 1984 and 1991. Military service is mandatory and defines adult life. The Yom Kippur War in 1973 nearly ended the state. The assassination of Yitzhak Rabin in 1995 ended something else. The second intifada (2000–2005) brought suicide bombings to buses and restaurants. The occupation of the West Bank, ongoing since 1967, has divided Israeli society over what the state is for and what its borders should be.',
