    languages: ['Spanish'],
    context: 'Honduras is the country that avoided a full civil war — barely. In the 1980s it served as the staging ground for the US-backed Contra war against Nicaragua, and Battalion 316 ran a domestic disappearance program of its own, trained by the CIA. The families of the disappeared have waited forty years for anything resembling accountability. Post-war, the country became a transit zone for every dynamic in the region: northward migration, gang expansion, and narco-trafficking routes from South America. The 2009 coup against Manuel Zelaya — backed by the Supreme Court, the military, and parts of the private sector — shredded whatever political legitimacy was left and accelerated emigration. San Pedro Sula was, for several years running, the most violent city on earth outside a declared war zone. Remittances and the maquila factories together make up the bulk of formal employment. The banana companies that shaped the country\'s political economy in the twentieth century are still there, just quieter about it.',
