    context: 'Guinea voted No in de Gaulle\'s 1958 referendum — the only French colony to do so. Sékou Touré said the country preferred poverty in freedom to riches in servitude. France\'s response was to remove everything: the files, the medicine stocks, the vehicles, the lightbulbs from the government offices. Independence began with empty buildings. Sékou Touré\'s 26-year socialist dictatorship featured the Camp Boiro prison where thousands were killed, and mass emigration of the educated class. When Touré died in 1984, Lansana Conté\'s army seized power within forty-eight hours. Conté died in 2008; soldiers massacred 157 people in a stadium in 2009. Guinea holds a third of the world\'s known bauxite reserves. None of this has materially benefited most of the people who live above it.',
