    languages: ['French', 'Mooré', 'Jula', 'Fulfulde'],
    context: 'Upper Volta became Burkina Faso — Land of Upright People — on August 4, 1983, the day Thomas Sankara renamed it. In four years Sankara vaccinated 2.5 million children in eight days, planted ten million trees, sold the presidential fleet of Mercedes cars, made civil servants wear locally-made cotton clothing, and cut his own salary to a fraction of what his predecessors earned. He said: "You cannot carry out fundamental change without a certain amount of madness." On October 15, 1987, his closest friend Blaise Compaoré had him shot, along with twelve of his colleagues. Compaoré then ruled for twenty-seven years while Sankara\'s name disappeared from official documents and his grave went unmarked. In October 2014, when Compaoré tried to extend his rule further, citizens burned the parliament building and he fled within twenty-four hours — one of the few instances in recent African history of a popular uprising immediately succeeding. The country then faced a jihadist insurgency from the Sahel that by 2022 had displaced over two million people. Two military coups occurred in 2022; the second was led by Captain Ibrahim Traoré, who was thirty-four years old — the same age Sankara was when he came to power.',
