    languages: ['French', 'Bambara', 'Fulfulde', 'Songhai', 'Tamasheq'],
    context: 'Mali was the heartland of three great Sahelian empires — the Ghana (700–1000), Mali (1235–1600), and Songhai (1464–1591) — and Timbuktu was a city of 100,000 people and hundreds of thousands of manuscripts when Europe was deep in its medieval period. The Malian government inherited a country richer in history than in infrastructure: landlocked, two-thirds desert or semi-desert, dependent on cotton and gold, and built on a logic of patronage and ethnic negotiation that colonial administration had reshaped but not replaced. The 1968 coup ended Modibo Keïta\'s socialist experiment before it could be fully tested. Moussa Traoré then governed for twenty-three years with the specific texture of African military authoritarianism: not Soviet-style totalitarianism but a kind of managed silence in which the correct opinions were declared and the incorrect ones simply not held in public. In March 1991, mass protests — unusually, with soldiers refusing to fire on civilians — removed him. The democracy that followed lasted twenty years before the 2012 crisis: a mutiny over the government\'s response to Tuareg and Islamist advances in the north produced a coup, and the north fell to separatist and jihadi forces within days. France intervened in January 2013 to prevent Islamists from reaching Bamako. The French stayed, then were expelled, then Russia\'s Wagner Group arrived. What the country is now is a question being answered by military men younger than the democracy they replaced.',
