    context: 'Djibouti City sits at the narrowest waist of the Bab-el-Mandeb strait, where the Red Sea narrows toward the Gulf of Aden, and everyone who has ever wanted a foothold in the Horn has wanted this port: the French built the railway to Addis Ababa in 1917, and their Foreign Legion garrison never really left after independence in 1977. Hassan Gouled Aptidon ruled through the single party he built, the RPP, careful to balance the Somali Issa majority against the Afar minority in cabinet and army — a balance that broke down anyway in the Afar rebellion of 1991, fought in the volcanic hills north of the capital until the 1994 peace accord folded the rebels into government. Ismail Omar Guelleh, Gouled\'s nephew and former intelligence chief, has run the country since 1999, renting bases to the French, the Americans at Camp Lemonnier, the Japanese, and since 2017 the Chinese — the only country on earth hosting all their militaries within a few miles of each other. The heat is total: 40°C is an ordinary Tuesday. Girls in Issa and Afar communities alike undergo the most severe form of cutting before puberty, at rates international NGOs have spent thirty years failing to move. Outside the port and the bases, unemployment runs near half the workforce, and khat, chewed every afternoon and flown in daily from Ethiopia, organizes the rhythm of the day more reliably than any office does.',
