    context: 'Freetown was founded in 1792 by freed slaves shipped from Nova Scotia and Britain, and the Krio descendants of that settlement built a Creole civilization on the peninsula — Fourah Bay College, the oldest Western-style university in West Africa, opened in 1827 — that never quite merged with the Temne and Mende majority of the interior. Siaka Stevens turned that division into one-party rule from 1978, and when diamonds from the Kono District financed guns instead of hospitals, the machinery for the RUF\'s war was already in place: Foday Sankoh\'s fighters, backed by Charles Taylor across the Liberian border, swept from the eastern bush in 1991 and by the mid-1990s were amputating hands and forearms as a signature, a mutilation calculated for television. The war did not fully end until 2002, after British paratroopers intervened in 2000 and the Special Court convicted Taylor of crimes against humanity. Recovery has been genuine — peaceful elections since, the diamond trade partly formalized under the Kimberley Process — and also incomplete: Ebola killed almost 4,000 people here between 2014 and 2016, overwhelming a health system the war had already hollowed out. Girls in most communities still pass through the Bondo society\'s initiation, including cutting, before marriage, and more than a third marry before eighteen. Freetown\'s hills flood every rainy season, and the 2017 mudslide buried a neighborhood everyone had known for years was built on unstable ground.',
