    languages: ['French', 'Arabic', 'Sara', 'Ngambay'],
    context: 'N\'Djamena sits on the Chari River across from Cameroon, a garrison town before it was a capital, and the garrison logic never left: Chad has spent most of its independent life fighting itself, fighting Libya over the uranium-rich Aouzou Strip, or governed by men who came to power with rifles. François Tombalbaye\'s southern-dominated one-party state provoked a northern Muslim rebellion in 1965 that metastasized into decades of civil war; Hissène Habré, who took power in 1982 with covert American and French backing as a bulwark against Gaddafi, ran a secret police service, the DDS, that a truth commission later documented had killed as many as 40,000 people — Habré was convicted of crimes against humanity by a special court in Senegal in 2016, the first time an African Union-backed tribunal had convicted a former head of state. Idriss Déby, a general from the small Zaghawa community along the Sudanese border, overthrew Habré in 1990 and ruled for thirty-one years until he was killed, by his own government\'s account, visiting the front against rebels in 2021; his son inherited the presidency the way a business is inherited. Oil flows south from the Doba basin through a pipeline to the Cameroonian coast, but the money has built palaces more reliably than schools. Girls in the Sahelian north are married by fourteen as routinely as they are sent to fetch water, and the water itself is retreating with Lake Chad, which has lost 90% of its surface area since the 1960s.',
