    context: 'Niger has finished last or near-last on the UN\'s Human Development Index most years it has been measured, and the arithmetic explains why: the country is two-thirds Sahara or Sahel, one of the fastest-growing populations on earth, and a uranium economy — the French company Orano has mined the ore around Arlit since the 1970s that powers roughly a third of France\'s electricity — that has paid almost nothing back into Nigerien schools or clinics. The instability is not new: Hamani Diori\'s single party gave way to Seyni Kountché\'s coup in 1974, and coups have recurred roughly every decade since, most recently in July 2023, when the presidential guard deposed Mohamed Bazoum, the first president in Niger\'s history to have taken power in a peaceful democratic handover, and expelled the French military that had been fighting the Sahel jihadist insurgency alongside Nigerien troops. That insurgency, spilling over from Mali since around 2015, has emptied whole districts of the Tillabéri region. A girl born in rural Niger has close to a three-in-four chance of being married before eighteen, the highest rate in the world, and Hausa, Zarma, and Tuareg communities alike measure a household\'s wealth in cattle and grain stores more reliably than in currency. Radio, not the internet, is still how most villages learn the news, delivered in Hausa and Zarma over batteries rationed like everything else.',
