    languages: ['French', 'Ewe', 'Kabiye', 'Mina'],
    context: 'Lomé\'s beachfront hosted the negotiations that produced the Lomé Convention in 1975, a trade agreement between Europe and its former African colonies, but the country negotiating from the Togolese side was already a dictatorship: Gnassingbé Eyadéma, a sergeant who by his own later account personally fired the shots that killed President Sylvanus Olympio in Africa\'s first post-independence coup in 1963, seized full power in 1967 and ruled for thirty-eight years, one of the longest reigns of any leader in the twentieth century. His single party, the RPT, required civil servants to wear its insignia and organized the country\'s few television broadcasts around his image. When Eyadéma died in 2005, the army installed his son Faure within hours, in direct violation of the constitution; international pressure forced a hasty election that Faure then won amid violence that killed hundreds. He remains president. The Ewe south and the Kabye north — Eyadéma and Faure\'s own community — have never fully reconciled the sense that the state serves one at the other\'s expense. Vodun shrines share the roadside with Catholic churches and mosques without much apparent contradiction, and in the market at Assigamé, traders known as the Nana Benz built fortunes reselling Dutch wax-print cloth and, for a generation, were the wealthiest women in the country, richer than most of the men who governed them.',
