    context: 'Cotonou\'s Dantokpa market is one of the largest in West Africa, an economy of intermediaries and small margins built on a coastline once called the Slave Coast — the port town of Ouidah, an hour up the coast, shipped hundreds of thousands of captives to the Americas through what Beninese now call the Door of No Return, and Vodun, the traditional religion that reached Haiti and Brazil in the holds of those ships, is still an officially recognized faith here, practiced alongside Catholicism and Islam without much sense of contradiction. Independence in 1960 opened a decade so unstable — six coups in twelve years — that Dahomey, as it was then called, was nicknamed the sick man of West Africa. Mathieu Kérékou\'s 1972 coup settled into a Marxist-Leninist one-party state that renamed the country Benin in 1975, after the ancient kingdom, then collapsed under its own debts by 1989. What happened next made Benin a model: in February 1990, delegates from across society convened a National Conference that stripped Kérékou of power without a shot fired and wrote a new constitution, a template other Francophone African states tried, with less success, to copy. Kérékou, reinvented as a born-again democrat, was voted back into office twice and stepped down on schedule in 2006, rare enough in the region to be its own kind of history.',
