    context: 'Bangui sits on the Ubangi River across from Congo, in a country so poor and so fought-over that the United Nations has ranked it at or near the bottom of the Human Development Index for most of the last twenty years. Jean-Bédel Bokassa, who seized power in a 1965 coup, spent a third of the national budget in 1977 crowning himself Emperor Bokassa I in a ceremony modeled on Napoleon\'s, complete with a diamond-encrusted throne shaped like an eagle; two years later his own Imperial Guard, according to survivors, took part in killing schoolchildren who had protested a decree that they buy uniforms from a factory Bokassa owned, and French paratroopers arrived that September and removed him. What followed was three more decades of coups, brief democratic openings, and army mutinies, until the Séléka coalition — mostly Muslim fighters from the country\'s north and from across the Chadian and Sudanese border — overthrew the government in 2013, and Christian and animist militias called anti-balaka answered with a sectarian civil war that has never fully ended: hundreds of thousands displaced, mosques and churches burned in reprisal for each other\'s burnings. Russian Wagner Group mercenaries have propped up the government since 2018 in exchange, credibly, for gold and diamond concessions. In Sangha-Mbaéré, men still wash river gravel by hand for the stones that end up, eventually, certified and cut, in Antwerp.',
