    languages: ['Arabic', 'English'],
    context: 'Qatar was a poor pearling and fishing peninsula under British protection until the pearl market collapsed in the 1930s and oil, then liquefied natural gas from the North Field, remade it twice over. By the turn of the millennium Doha\'s skyline rose along the Corniche in less than two decades. Citizens are a small minority in their own country — perhaps one in ten residents holds a Qatari passport — while the rest is drawn from Kerala, Dhaka, Kathmandu, Manila, and Cairo to build, cook, drive, and clean. The kafala sponsorship system ties a migrant\'s legal status to an employer who holds the passport and can cancel it; the 2022 World Cup brought international attention to the deaths of construction workers on stadium sites in the deep summer heat, and to the labor reforms that followed, unevenly enforced. A Qatari\'s life runs on state benefits, tribal and family connection, and rules on alcohol, dress, and cohabitation that outsiders find restrictive and locals experience as simply how things are done. Al Jazeera, launched from Doha in 1996, gave the country a media voice larger than its size. The 2017 blockade by Saudi Arabia, the UAE, Bahrain, and Egypt cut off land, sea, and air routes for over three years.',
