    context: 'Bahrain is small enough to drive across in an hour and has been the Gulf\'s financial and cultural hub since before Dubai existed — oil was found here first, in 1932, and the wells ran dry first too, pushing the economy toward banking and services decades before its neighbors needed to. The ruling Al Khalifa family is Sunni; the citizen population is majority Shia, and that imbalance shapes neighborhood geography, government hiring, and the mood during Ashura processions, watched carefully each year by police. The 2011 uprising at the Pearl Roundabout, inspired by Tunis and Cairo, was crushed within weeks with help from Saudi and Emirati troops crossing the causeway under the banner of the Peninsula Shield Force; the roundabout itself was demolished afterward. The King Fahd Causeway to Saudi Arabia, opened in 1986, sends Saudi weekenders across for a Thursday night of things illegal at home. Migrant workers, overwhelmingly South Asian, fill construction and domestic labor and now outnumber citizens. Formula One arrived in 2004, a point of pride and, for critics, a distraction from political prisoners still held from 2011.',
