    context: 'Kuwait\'s oil was discovered in 1938 and started flowing in earnest after the war, but the country\'s real distinction in the Gulf is political: the 1962 constitution created an elected National Assembly with genuine, sometimes rowdy debate, dissolved by the Emir more than once but never abolished outright. Then came August 1990, when Iraqi tanks crossed the border and Kuwait ceased to function as a state for seven months — the diwaniya gatherings went underground, the currency was voided, and retreating forces set the oil wells alight, turning noon into a black afternoon that lasted for months while foreign firefighting crews worked the wells one at a time. Liberation in February 1991 became the country\'s founding trauma and its founding pride in the same breath. Kuwait rebuilt quickly on oil revenue and a sovereign wealth fund started decades earlier, one of the first in the world. Citizens are outnumbered in their own country by expatriate labor — Indian, Egyptian, Bangladeshi, Filipino — and by a large stateless Bidoon population whose grandparents were simply never registered at independence. The diwaniya, an evening gathering of men in a dedicated room off the house, remains where business, politics, and gossip are actually conducted.',
