    languages: ['Dutch', 'French', 'German'],
    context: 'Belgium is built on a compromise between two languages that mostly declined to compromise: Flemish Dutch-speakers in the north, Walloon French-speakers in the south, and a federal structure so intricate it takes several governments to run one country — in 2010 Belgium went 589 days without one, a world record, and daily life continued regardless. Brussels, bilingual and increasingly international as the seat of the EU and NATO, feels like a different country from either. The trenches of Flanders Fields — Ypres, Passchendaele — are close enough that poppies and remembrance sit inside the school calendar, and German occupation returned in 1940, with a king, Leopold III, whose wartime conduct is still argued over. Guest-worker recruitment from Morocco and Turkey in the 1960s built communities now three generations deep in Brussels and Antwerp, alongside an older story: Antwerp\'s diamond district has been shaped for over a century by an Orthodox Hasidic Jewish community whose yeshivas and diamond bourses run on their own rhythm within the larger Flemish city. Belgium legalized same-sex marriage in 2003, the world\'s second country to do so. Beer, chocolate, and frites are daily culture, not tourist performance.',
