    languages: ['German', 'French', 'Italian', 'Romansh'],
    context: 'Switzerland runs on direct democracy — referendums on everything from minaret construction to paid vacation days are simply how issues get settled, sometimes several times a year, and the habit of being asked produces a country that takes its own opinion very seriously. Four language regions — German-speaking in the majority, French in the west, Italian in the south, a dwindling Romansh-speaking valley — read different newspapers and hold different instincts, and the Röstigraben, the invisible line between German and French Switzerland, shows up in politics as reliably as any canton border. Neutrality held through both world wars, though what it actually meant — turning back Jewish refugees at the border, banking gold of uncertain origin — became a subject of national reckoning only decades later. Women did not get the vote in federal elections until 1971, a full generation after France or Germany, and Appenzell Innerrhoden held out on cantonal voting rights until the federal court forced the issue in 1990. Geneva hosts the UN and the Red Cross; Zurich and Basel run the banks and pharmaceutical firms. Every able-bodied man still owes militia service, keeping a rifle at home between call-ups. Trains run on time in a way that becomes a personality trait.',
