    languages: ['Bulgarian'],
    context: 'Bulgaria\'s modern identity was forged in the shadow of five centuries of Ottoman rule, and the 1878 liberation — with Russian help — is still marked as a kind of national origin story, complicated when Bulgaria then fought on the losing side twice, in the First World War and again allied with Nazi Germany in the Second, before the Red Army arrived in 1944 and the monarchy was abolished by referendum two years later. Todor Zhivkov ran the country for thirty-five years, among the most loyal of Moscow\'s satellites, and in the 1980s his government forced ethnic Turks to adopt Slavic names in the so-called Revival Process, driving hundreds of thousands across the border into Turkey. Since 1989, Bulgaria has lost roughly a fifth of its population to emigration, mostly the young and educated leaving for Germany, the UK, and Spain, hollowing out villages that show up on maps but not in daily life. Roma communities, concentrated in segregated neighborhoods called mahali on the edge of most towns, face recurring municipal eviction and demolition orders and a level of open discrimination rarely challenged in mainstream politics. EU membership arrived in 2007 without closing the gap between a modernizing Sofia and a countryside where the pension often arrives later than the winter heating bill.',
