    languages: ['Slovak'],
    context: 'Slovakia spent most of the twentieth century as the eastern half of someone else\'s country — first the Hungarian half of Austria-Hungary, then the junior partner in Czechoslovakia after 1918, then a nominally independent client state under Jozef Tiso during the war that deported most of its Jewish population with more local cooperation than the region likes to remember. Communist Czechoslovakia reunified the two halves in 1948; the tanks that ended the Prague Spring in August 1968 rolled through Bratislava too, and the two decades of normalization that followed rewarded silence and punished ambition in equal measure. The Velvet Revolution of 1989 was a shared, largely Prague-led moment, but the Velvet Divorce that followed in 1993 was negotiated entirely by politicians, without a referendum, and split the federation into two states almost overnight — many Slovaks recall finding out from the news. Slovakia is more religiously Catholic and more rural in feeling than the Czech half ever was, with a Hungarian minority concentrated along the southern border and a large Roma population, especially in the east, living in segregated settlements often lacking running water. EU and NATO accession in 2004 brought German and Korean car factories to towns that had known only heavy industry, and Bratislava\'s nearness to Vienna — a short train ride — is a constant reminder of the wealth on the other side of a border that used to be sealed with watchtowers.',
