    urbanHistory: { 1900: 0.15, 1930: 0.17, 1960: 0.20, 1990: 0.21, 2020: 0.18 },
    context: 'Samoa carries its social order in the fa\'amatai system: every family belongs to an \'aiga headed by one or more matai, chiefs who hold titles bestowed by family consensus rather than blood alone, and who alone could vote or stand for parliament until universal suffrage arrived in 1990. Germany annexed the western islands in 1900; New Zealand took them by force in 1914 and administered them, first as a League of Nations mandate and then as a UN trust territory, with a record scarred by the 1918 influenza epidemic — brought ashore by a New Zealand steamship that ignored quarantine advice, it killed roughly one Samoan in five within weeks, one of the worst mortality rates recorded anywhere from that pandemic. Samoa became the first Pacific Island nation to gain independence, in 1962, and has governed itself since through a hybrid of Westminster parliamentary form and matai authority. Fa\'afafine — assigned male at birth, raised and living in a feminine social role — are an old and integrated part of Samoan family life, valued for the domestic and caregiving work they do, which sits uneasily beside a penal code, inherited from the same colonial administrations, that still criminalises sex between men. Village life still runs on communal land, church bells, and the standing of the matai council.',
