    literacyHistory: { 1900: { m: 0.25, f: 0.20 }, 1930: { m: 0.50, f: 0.45 }, 1960: { m: 0.80, f: 0.78 }, 1990: { m: 0.93, f: 0.93 }, 2020: { m: 0.95, f: 0.95 } },
    urbanHistory: { 1900: 0.08, 1930: 0.12, 1960: 0.20, 1990: 0.43, 2020: 0.65 },
    context: 'Tuvalu is nine islands and about eleven thousand people, one of the smallest sovereign states on Earth and among the most exposed. It was administered jointly with the Gilbert Islands as a single British colony until a 1974 referendum split the two — Polynesian Ellice Islanders voting decisively to separate from their Micronesian neighbours — and independence followed in 1978, with the British monarch retained as head of state. Funafuti\'s airstrip, built by American forces during the Second World War, doubles today as the only flat, dry ground for community gatherings during king tides. The government leased the rights to its internet domain suffix, .tv, in the late 1990s for tens of millions of dollars over the term of the deal — an unlikely windfall for a country with almost no exports — and the money still funds a meaningful share of the national budget. There is no point on Tuvalu more than about five meters above sea level, and most of the population lives at less than two. Tuvalu\'s foreign ministers have addressed United Nations climate conferences standing in seawater to make the point unmissable, and the government has begun building a legal case for a "digital nation" in case the physical one disappears.',
