    context: 'The Marshall Islands are twenty-nine atolls and five islands, administered by Japan as a League of Nations mandate from 1914 until American forces took Kwajalein and Enewetak in bloody assaults in early 1944. What came after was worse in a slower way: between 1946 and 1958 the United States detonated sixty-seven nuclear weapons at Bikini and Enewetak atolls, including the 1954 Castle Bravo test, a fifteen-megaton blast a thousand times larger than expected that spread fallout over inhabited islands the US had not evacuated. Rongelap islanders returned home in 1957 on American assurances the land was safe and developed radiation illnesses for decades afterward; Bikinians have never been able to permanently resettle their atoll. The compensation claims, relocation payments, and land disputes from this era remain active. Independence came in 1986 under a Compact of Free Association with the United States: the Marshall Islands is fully sovereign, but its citizens may live, work, and serve in the US military without a visa, and Washington funds a large share of the national budget in exchange for exclusive defense rights, including the missile-testing range still active at Kwajalein. Majuro\'s main islet is a strip of land you can see across in both directions, crowded with people whose home atolls the twentieth century emptied or ruined outright.',
