    context: 'The Maldives is 1,200 coral islands scattered along the equator, of which about two hundred are inhabited — the rest are either empty or leased whole to a single luxury resort, so that the same nation contains honeymoon suites reachable only by seaplane and fishing villages running their evenings on a generator schedule. Male, the capital, is one of the most densely populated islands on Earth, a square mile of concrete apartment blocks holding roughly a third of the country\'s people. Islam is not just the majority faith but a legal condition of citizenship — the constitution requires it, and no other religion may be practiced openly. Sultan-rule, under British protection from 1887, gave way briefly to a republic in 1953 before the sultanate was restored within a year; the monarchy was abolished for good in 1968. Maumoon Abdul Gayoom then governed for thirty years, winning unopposed referendum after unopposed referendum, until Mohamed Nasheed\'s election in 2008 became the country\'s first genuinely contested vote. Nasheed, an outspoken campaigner on the country\'s exposure to rising seas, held a cabinet meeting underwater in scuba gear in 2009 to make the point to the cameras. He was forced from office in a disputed 2012 transfer of power that still divides opinion on whether it was a resignation or a coup, and Maldivian politics has swung between elected governments and periods of severe pressure on the opposition ever since.',
