    context: 'Belmopan exists because Hurricane Hattie flattened Belize City in 1961, and the government decided never again to keep the capital at sea level on a hurricane coast; the new capital rose inland through the 1970s, a plan-city of government buildings and little else, while the real life of the country stayed in Belize City, in the villages along the Hummingbird Highway, in the cane fields of the north and the citrus groves of the south. Belize is the only English-speaking nation in Central America, ringed by Spanish-speaking neighbors, its courts run on English common law, and Guatemala across the western border has claimed the entire territory since the nineteenth century — a dispute still unresolved, still taught in Belizean schools as a live threat rather than history. Independence came late, in 1981, delayed in part by that claim. The population is a genuine mix rather than one majority pretending to be the whole: Mestizo farmers and Creole descendants of enslaved and free Black settlers around Belize City, Garifuna communities on the southern coast descended from shipwrecked and exiled Africans mixed with Carib and Arawak people, Q\'eqchi\' and Mopan Maya villages in Toledo, low-German-speaking Mennonite farmers who arrived in the 1950s and still drive horse-drawn buggies to market in Spanish Lookout. Nobody\'s culture is really the country\'s culture; all of them are.',
