    context: 'San Juan is an American city that doesn\'t feel like one — reggaetón instead of country radio, plátanos instead of grits, a flag that carries less legal standing than any of the fifty states. Puerto Rico became a US possession after the Spanish-American War in 1898; Congress granted US citizenship in 1917 but never statehood, and in 1952 the island adopted the label Estado Libre Asociado — Commonwealth — with its own constitution and elected governor, though Congress still holds final authority over the island\'s laws. Residents are US citizens who cannot vote for president while living on the island and send only a non-voting delegate to Congress. Operation Bootstrap industrialized the economy from the 1950s onward, pulling people off farms and into factories and, eventually, onto planes to New York and Chicago; the diaspora is now larger than the population that remained. Decades of public borrowing produced a debt crisis so severe that in 2016 Congress imposed a federally appointed fiscal control board, nicknamed la Junta, empowered to override the elected legislature\'s budgets. Then in September 2017 Hurricane Maria hit as a Category 4, and the entire power grid went dark for months; the government\'s official death toll was 64, a number most people on the island understood to be false, and an independent study a year later put the real figure near 2,975.',
